contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs: recipient and amount
    function run(address to, uint256 value) public payable {
        require(true);

        // record observable state before
        address owner = c.owner();
        uint256 totalBefore = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(address(this));
        uint256 balToBefore = c.balanceOf(to);
        bool frozenSenderBefore = c.frozenAccount(address(this));
        bool frozenToBefore = c.frozenAccount(to);

        // perform the transfer and record whether it reverted
        bool reverted;
        try c.transfer(to, value) returns (bool res) {
            reverted = !res; // transfer returns true on success, but treat false as revert-like
        } catch {
            reverted = true;
        }

        // read after-state
        uint256 totalAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(address(this));
        uint256 balToAfter = c.balanceOf(to);
        bool frozenSenderAfter = c.frozenAccount(address(this));
        bool frozenToAfter = c.frozenAccount(to);

        // General rule:
        // If the call did not revert, totalSupply is preserved and balances change by exactly value
        // from sender to recipient. If it reverted, totalSupply and balances are unchanged.
        assert(
            (
                reverted &&
                totalAfter == totalBefore &&
                balSenderAfter == balSenderBefore &&
                balToAfter == balToBefore &&
                frozenSenderAfter == frozenSenderBefore &&
                frozenToAfter == frozenToBefore
            ) || (
                !reverted &&
                totalAfter == totalBefore &&
                balSenderBefore >= value &&
                balSenderAfter + value == balSenderBefore &&
                balToAfter == balToBefore + value &&
                frozenSenderAfter == frozenSenderBefore &&
                frozenToAfter == frozenToBefore
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // target: account to freeze/unfreeze
    // freeze: desired freeze boolean
    function run(address target, bool freeze) public payable {
        require(target != address(0));

        // read before value
        bool before = c.frozenAccount(target);

        // attempt to call freezeAccount; capture whether it reverted
        bool reverted;
        try c.freezeAccount(target, freeze) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after value
        bool after = c.frozenAccount(target);

        // If the call reverted, frozenAccount must be unchanged; otherwise it must equal 'freeze'.
        assert(reverted ? (after == before) : (after == freeze));
    }

    receive() external payable {}
}

