contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt mintToken and burn as msg.sender == this contract (which is the owner because test deploys c)
    // Parameters: target to mint to, mintedAmount to mint, burnAmount to burn from this contract (owner)
    function run(address target, uint256 mintedAmount, uint256 burnAmount) public payable {
        require(target != address(0));
        // Read before-values
        uint256 before_total = c.totalSupply();
        uint256 before_balance_target = c.balanceOf(target);
        uint256 before_balance_self = c.balanceOf(address(this));
        bool mint_reverted;
        // Attempt mintToken: record whether it reverts
        try c.mintToken(target, mintedAmount) {
            mint_reverted = false;
        } catch {
            mint_reverted = true;
        }
        // After mint attempt read values
        uint256 after_total_after_mint = c.totalSupply();
        uint256 after_balance_target_after_mint = c.balanceOf(target);
        uint256 after_balance_self_after_mint = c.balanceOf(address(this));

        // Now attempt burn from this contract (owner). It should only succeed if this contract has enough balance and is owner.
        bool burn_reverted;
        try c.burn(burnAmount) returns (bool ok) {
            burn_reverted = false;
        } catch {
            burn_reverted = true;
        }
        uint256 after_total = c.totalSupply();
        uint256 after_balance_target = c.balanceOf(target);
        uint256 after_balance_self = c.balanceOf(address(this));

        // General rule asserted:
        // 1) If mint did not revert then totalSupply increased by exactly mintedAmount and target's balance increased by exactly mintedAmount.
        //    Otherwise totalSupply and balances remained unchanged by the mint attempt.
        // 2) If burn did not revert then totalSupply decreased by exactly burnAmount and this contract's balance decreased by exactly burnAmount.
        //    Otherwise totalSupply and balances remained unchanged by the burn attempt.
        assert(
            (
                (!mint_reverted && after_total_after_mint == before_total + mintedAmount && after_balance_target_after_mint == before_balance_target + mintedAmount && after_balance_self_after_mint == before_balance_self)
                || (mint_reverted && after_total_after_mint == before_total && after_balance_target_after_mint == before_balance_target && after_balance_self_after_mint == before_balance_self)
            )
            &&
            (
                (!burn_reverted && after_total == (after_total_after_mint - burnAmount) && after_balance_self == (after_balance_self_after_mint - burnAmount) && after_balance_target == after_balance_target_after_mint)
                || (burn_reverted && after_total == after_total_after_mint && after_balance_self == after_balance_self_after_mint && after_balance_target == after_balance_target_after_mint)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function performing the property test
    // targetBurn is the amount we attempt to burn as the owner (this contract)
    function run(uint256 targetBurn) public payable {
        // read observable before-values
        uint256 before_total = c.totalSupply();
        uint256 before_balance_self = c.balanceOf(address(this));

        // attempt burn and record whether it reverted
        bool burn_reverted;
        try c.burn(targetBurn) returns (bool ok) {
            burn_reverted = false;
        } catch {
            burn_reverted = true;
        }

        // read after-values
        uint256 after_total = c.totalSupply();
        uint256 after_balance_self = c.balanceOf(address(this));

        // General rule:
        // If burn did not revert then before_balance_self >= targetBurn and
        // after_total == before_total - targetBurn and after_balance_self == before_balance_self - targetBurn.
        // If burn reverted then total and balances are unchanged.
        assert(
            ( !burn_reverted
                && before_balance_self >= targetBurn
                && after_total == before_total - targetBurn
                && after_balance_self == before_balance_self - targetBurn
            )
            ||
            ( burn_reverted
                && after_total == before_total
                && after_balance_self == before_balance_self
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters for target and amount
    function run(address target, uint256 mintedAmount) public payable {
        require(target != address(0)); // avoid trivial zero-address transfer/reverts due to checks elsewhere

        // read before-values
        uint256 beforeBalance = c.balanceOf(target);
        uint256 beforeTotal = c.totalSupply();

        // attempt the mint and detect revert
        bool reverted;
        try c.mintToken(target, mintedAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterBalance = c.balanceOf(target);
        uint256 afterTotal = c.totalSupply();

        // Assert the general rule: if mint succeeded, both balance and totalSupply increased by mintedAmount;
        // if it reverted, neither changed.
        assert((!reverted && afterBalance == beforeBalance + mintedAmount && afterTotal == beforeTotal + mintedAmount) || (reverted && afterBalance == beforeBalance && afterTotal == beforeTotal));
    }

    receive() external payable {}
}
